const std::size_t rangeSize = end - start;
std::vector<std::size_t> indices(rangeSize);
std::iota(indices.begin(), indices.end(), start);

#pragma omp parallel for schedule(dynamic)
for (std::size_t idx = 0; idx < rangeSize; ++idx) {
    const std::size_t i = indices[idx];
    Particle& p = particles[i];

    // Update position with velocity
    p.x += p.vx * deltaTime;
    p.y += p.vy * deltaTime;

    // Apply boundary conditions (elastic collision)
    if (std::abs(p.x) > boxWidth) {
        p.x = std::copysign(boxWidth, p.x);
        p.vx *= -elasticity;
    }
    if (std::abs(p.y) > boxWidth) {
        p.y = std::copysign(boxWidth, p.y);
        p.vy *= -elasticity;
    }

    // Apply gravity
    p.vy += g * deltaTime;

    // Update velocity (simple Euler integration)
    p.vx += p.ax * deltaTime;
    p.vy += p.ay * deltaTime;

    // Reset acceleration (assuming it's temporary)
    p.ax = 0.0f;
    p.ay = 0.0f;
}
// END_CODE

